  channel_order_recommendation:   { consumers: [], disposition: "feed_only", kind: "update",     what: "the learned best lead channel for this brokerage (advisory)" },
  copy_variant_promoted:          { consumers: [], disposition: "feed_only", kind: "update",     what: "an A/B copy variant won on reply rate and was promoted" },
  health_lifecycle_play:          { consumers: [], disposition: "feed_only", kind: "update",     what: "a decaying relationship routed to the right manager for a re-engagement play" },
  second_opinion_requested:       { consumers: [], disposition: "feed_only", kind: "update",     what: "a strategic play asked a second manager for a complementary read (the huddle)" },
  source_allocation_advice:       { consumers: [], disposition: "feed_only", kind: "update",     what: "lead-source enable/disable advice from real conversion + ROI" },
  source_lifetime_health_advice:  { consumers: [], disposition: "feed_only", kind: "update",     what: "lead-source lifetime-quality advice (relationships that LAST, not just first close)" },
  voice_action:                   { consumers: [], disposition: "feed_only", kind: "update",     what: "the VOICE ADMIN executed a spoken action (task / activity / client message) — the owning manager records it on the bus so every voice command is visible + accountable in the Command Center, exactly like the text command bar" },
  repurpose_shorts_handoff:       { consumers: ["asset_manager"], disposition: "handled", kind: "handoff", what: "Campaign Orchestrator → Asset Manager: a broadcast marketing reel is done and being distributed — AUTONOMOUSLY cut platform SHORTS from it. The Asset Manager re-commissions the same content as vertical reels (tiktok/instagram) for the social channels the primary didn't cover, through the Director/commissionVideo pipeline (real render + bookends + QR + gating). Replaces the old manual snippets/repurpose UI process with a managed, on-the-bus decision" },
  campaign_recovered:             { consumers: [], disposition: "feed_only", kind: "update",     what: "the Campaign Orchestrator AUTONOMOUSLY caught a stalled campaign (an already-approved 'scheduled' launch that never fired) and RE-LAUNCHED it through the compliance-gated publisher — the agent never had to redo the work. Routed to cron_manager (m618: TOMBSTONE — was campaign_orchestrator -> marketing_agent, a same-manager route once the retired seat's survivor is campaign_orchestrator; cron_manager owns loop-health/self-heal visibility for this REAPER catch). Surfaced in the Command Center's managers-talking feed so the team sees marketing never falls through the cracks" },
  win_story:                      { consumers: [], disposition: "feed_only", kind: "update",     what: "a farm-area win worth telling the neighborhood (social proof)" },
  trid_disclosure_clock:          { consumers: [], disposition: "feed_only", kind: "update",     what: "a TRID disclosure clock is ticking on a deal — keep the timeline honest" },
