  deal_play_ads_ready:            { consumers: [], disposition: "feed_only", kind: "handoff",    what: "Deal Play hop 4: Ads Manager staged the ad drafts -- the play is staged end to end, one review to launch" },
  fire_drill_opened:              { consumers: [], disposition: "feed_only", kind: "escalation", what: "a fire-drill opened — the team converges on an urgent situation" },
