  newsletter_seo_score_low:     { consumers: [], disposition: "feed_only", kind: "update", what: "a scheduled newsletter was DEFERRED because its stored SEO score is under the send gate — Data Steward → Campaign Orchestrator (m618: TOMBSTONE — was campaign_orchestrator -> marketing_agent, a same-manager route once the retired seat's survivor is campaign_orchestrator) (app/api/cron/publish-newsletters)" },
