  isa_appointment_scheduled:   { consumers: ["shopping_agent", "listing_concierge"], disposition: "handled", kind: "handoff", what: "AI ISA booked an appointment through the GENERAL booking path (not a dial-batch call) — the side-appropriate concierge proposes the prep follow-up (lib/ai-isa/appointment-scheduler.ts)" },
  message_needs_response:      { consumers: ["ai_isa"], disposition: "handled", kind: "update", what: "a client portal message has gone unanswered past the reply SLA — AI ISA notifies the assigned agent directly (app/api/cron/message-needs-response)" },
  onboarding_completed:        { consumers: ["campaign_orchestrator"], disposition: "handled", kind: "update", what: "an agent finished onboarding + certification — Recruiting Manager hands it to Campaign Orchestrator, which proposes a gated welcome/congrats social post (lib/onboarding/certification-engine.ts completeOnboarding)" },
  business_card_approved:      { consumers: ["sphere_of_influence"], disposition: "handled", kind: "update", what: "a scanned business card was classified SPHERE or CONTACT (lib/contacts/card-classifier.ts classifyCardSubject; wave 48, owner ruling 2026-09-10 — a card is never ASSUMED a contact) — Sphere of Influence proposes the warm first-touch intro (app/actions/business-card/business-card-actions.ts). The four other classes route on their own signal_type below: business_card_potential_contact_candidate / business_card_recruit_candidate / business_card_vendor_candidate / business_card_classification_needed" },
  business_card_potential_contact_candidate: { consumers: ["ai_isa"], disposition: "handled", kind: "handoff", what: "wave 48 (owner ruling 2026-09-10): a scanned business card was classified a POTENTIAL contact (reader/notes/picker — not yet a qualified client) — AI ISA proposes ONE gated first-touch through the canonical consent-gated contact engagement; nothing sends without a human approval (app/actions/business-card/business-card-actions.ts, lib/kernel/event-reactor.ts D-decies)" },
  business_card_recruit_candidate: { consumers: ["recruiting_manager"], disposition: "handled", kind: "handoff", what: "wave 48 (owner ruling 2026-09-10, 'other agents are users'): a scanned business card was classified AGENT (a fellow real-estate agent, possibly at another brokerage) — a recruiting prospect, NEVER a CRM contact. The action already creates the recruits row; Recruiting Manager surfaces the fresh prospect to the recruiter (app/actions/business-card/business-card-actions.ts)" },
  business_card_vendor_candidate: { consumers: ["asset_manager"], disposition: "handled", kind: "handoff", what: "wave 48 (owner ruling 2026-09-10): a scanned business card was classified VENDOR (an inspector/lender/photographer/etc.) — the action already creates the pending vendors row; Asset Manager (which sources the content-creation trades — photographer/videographer/drone_pilot/3d_tour are exactly its own supply chain) sees the fresh bench candidate. Other trades still reach the vendor book; Asset Manager is the cue, not the gate (app/actions/business-card/business-card-actions.ts)" },
  business_card_classification_needed: { consumers: [], disposition: "feed_only", kind: "update", what: "wave 48 (owner ruling 2026-09-10): a scanned business card's reader fields and the agent's notes were BOTH silent, and no existing user/contact/vendor matched by email/phone — the card stays UNCLASSIFIED (never silently filed as a contact) until a human picks a class on the card review surface. Feed-only by design: classification is a judgement about who this person is, not something to automate (app/actions/business-card/business-card-actions.ts)" },
  task_due:                    { consumers: ["deal_coordinator"], disposition: "handled", kind: "update", what: "a task is due within 24h — Deal Coordinator reminds the assigned agent directly (app/api/cron/task-due)" },
  commission_paid:             { consumers: ["deal_coordinator"], disposition: "handled", kind: "update", what: "a commission was recorded — Finance Manager hands it to Deal Coordinator (owns the transaction it closes out), which flags the earnings ledger to the producing agent (lib/kernel/financial.ts createCommissionRecord, canonical table agent_commissions; wave 51: FROM/TO were both finance_manager, an invalid self-route that never published — the handler now keys on deal_coordinator:commission_paid)" },
  review_received:             { consumers: ["sphere_of_influence"], disposition: "handled", kind: "update", what: "a review landed — Sphere of Influence proposes a gated thank-you when the rating is positive/unrated; a lower rating is left for a human (lib/reputation/review-landed.ts)" },
  website_visitor_identified:  { consumers: ["campaign_orchestrator"], disposition: "handled", kind: "update", what: "a known website visitor was re-identified — Campaign Orchestrator ensures newsletter enrollment (the same idempotent, opt-out-honoring path newsletter_touch_handoff uses; app/api/track/identify)" },
  task_completed:              { consumers: [], disposition: "feed_only", kind: "update", what: "a transaction task was completed — Deal Coordinator hands it to Finance Manager for commission-readiness visibility (app/actions/tasks.ts completeTask; wave 51: FROM/TO were both deal_coordinator, an invalid self-route that never published)" },
  listing_archived:            { consumers: [], disposition: "feed_only", kind: "update", what: "a listing was archived — Listing Concierge hands the records-lifecycle moment to Data Steward (app/actions/listings.ts; wave 51: FROM/TO were both listing_concierge, an invalid self-route that never published)" },
